const payload = $('Execute Workflow Trigger').item.json || {};
const msg = payload.message || payload.body?.message || payload;
const rawText = String(msg?.text || payload.text || '').trim();
const chatId = msg?.chat?.id || payload.chatId || '';

function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0111/g, 'd')
    .replace(/\u0110/g, 'D');
}

const text = normalize(rawText);
let action = 'help';

if (/\b(gui mail|gui email|send mail|send email|soan mail|soan email|compose mail|compose email)\b/.test(text)) {
  action = 'send_email';
} else if (/\b(tra loi mail|tra loi email|reply mail|reply email)\b/.test(text)) {
  action = 'reply_email';
} else if (/\b(doc mail|doc email|read mail|read email|noi dung mail|noi dung email|open mail|open email|chi tiet mail|chi tiet email)\b/.test(text)) {
  action = 'read_email';
} else if (/\b(tim mail|tim email|search mail|search email|tim kiem mail|tim kiem email)\b/.test(text)) {
  action = 'search_email';
} else if (/\b(xem mail|xem email|inbox|hop thu|hop thu den|mail moi|email moi|check mail|check email|kiem tra mail|kiem tra email)\b/.test(text)) {
  action = 'list_inbox';
} else if (/\b(gmail|mail|email)\b/.test(text)) {
  action = 'list_inbox';
}

return [{ json: { payload, message: msg, chatId, rawText, text, action } }];

const workflowMap = {
  list_inbox: 'Sub-workflow: Google Gmail - List Inbox',
  read_email: 'Sub-workflow: Google Gmail - Read Email',
  send_email: 'Sub-workflow: Google Gmail - Send Email',
  search_email: 'Sub-workflow: Google Gmail - Search Email',
  reply_email: 'Sub-workflow: Google Gmail - Reply Email',
  help: 'Sub-workflow: Google Gmail - Help'
};

const workflowName = workflowMap[$json.action] || workflowMap.help;
return [{ json: { ...$json, workflowName } }];

const workflows = $input.item.json.data || [];
const source = $('Chon Workflow Gmail').item.json;
const found = workflows.find((w) => w.name === source.workflowName);

if (!found) {
  return [{ json: { ...source, hasWorkflow: false, response: `Khong tim thay workflow con: ${source.workflowName}` } }];
}

return [{ json: { ...source, hasWorkflow: true, workflowId: found.id } }];

